(async () => {
  const token = 'REDACTED';
  localStorage.setItem('shop_refresh_token', token);
  const csrf = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';
  const tid = '2fdee1ac-4674-41ee-b89e-87b45643f789';
  const refreshRes = await fetch(`/shop/api/session/refresh?tenant_id=${tid}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-CSRF-Token': csrf
    },
    credentials: 'same-origin',
    body: JSON.stringify({ refresh_token: token })
  });
  const refreshText = await refreshRes.text();
  let refreshBody = {};
  try { refreshBody = JSON.parse(refreshText); } catch {}
  if (refreshBody.refresh_token) localStorage.setItem('shop_refresh_token', refreshBody.refresh_token);
  const cardsRes = await fetch(`/shop/api/user/cards?tenant_id=${tid}`, {
    headers: { 'Accept': 'application/json', 'X-CSRF-Token': csrf },
    credentials: 'same-origin'
  });
  const cardsBody = await cardsRes.json().catch(() => ({}));
  const list = cardsBody.cards || cardsBody.payment_methods || cardsBody.data || [];
  return JSON.stringify({
    csrf_len: csrf.length,
    refresh_http: refreshRes.status,
    refresh_snippet: refreshText.slice(0, 200),
    customer_id: refreshBody.profile?.id || refreshBody.customer_id || refreshBody.id,
    cards_http: cardsRes.status,
    cards_keys: Object.keys(cardsBody),
    cards: Array.isArray(list) ? list.map(c => ({ mask: c.card_masked || c.masked_pan || c.label, brand: c.card_brand || c.brand, id: c.id })) : cardsBody
  });
})()

