(async () => {
  const tid = '2fdee1ac-4674-41ee-b89e-87b45643f789';
  const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
  let token = localStorage.getItem('shop_refresh_token');
  const refreshRes = await fetch(`/shop/api/session/refresh?tenant_id=${tid}`, {
    method: 'POST', credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-CSRF-Token': csrf },
    body: JSON.stringify({ refresh_token: token })
  });
  const rb = await refreshRes.json().catch(() => ({}));
  if (rb.refresh_token) { localStorage.setItem('shop_refresh_token', rb.refresh_token); token = rb.refresh_token; }
  // select *5953 for M2 decline
  const btn5953 = [...document.querySelectorAll('button')].find(b => /\*5953/.test(b.textContent || ''));
  if (btn5953) btn5953.click();
  await new Promise(r => setTimeout(r, 300));
  const selected = [...document.querySelectorAll('button')].filter(b => /Картой \*/.test(b.textContent||'')).map(b => ({text: b.textContent.trim(), aria: b.getAttribute('aria-pressed') || b.getAttribute('aria-selected') || b.className.slice(0,80)}));
  const inline = document.querySelector('[data-testid="payment-method-inline-error"]');
  return JSON.stringify({ refresh_http: refreshRes.status, customer: rb.profile?.id, selected, inline: inline?.textContent || null });
})()

(async () => {
  const pay = [...document.querySelectorAll('button')].find(b => (b.textContent || '').trim() === 'Оплатить');
  if (!pay) return JSON.stringify({ error: 'no pay button' });
  pay.click();
  // wait for one_click response / UI update
  for (let i = 0; i < 40; i++) {
    await new Promise(r => setTimeout(r, 500));
    const inline = document.querySelector('[data-testid="payment-method-inline-error"]');
    const sheet = document.querySelector('.pm-sheet, [data-testid="payment-methods-sheet"]') || [...document.querySelectorAll('*')].find(el => (el.textContent||'').includes('Способ оплаты') && el.querySelector && el.querySelector('button'));
    const newCard = document.querySelector('[data-testid="new-card-form"], .new-card-form');
    const payText = [...document.querySelectorAll('button')].find(b => /Оплатить|Повторить|смените|Недостаточно|Сбой|связи/.test(b.textContent||''));
    if (inline || (payText && /Недостаточно|Повторить|Сбой|смените|Отказ/.test(payText.textContent||''))) {
      return JSON.stringify({
        waited_ms: (i+1)*500,
        inline: inline?.textContent?.trim() || null,
        pay_btn: payText?.textContent?.trim() || null,
        sheet_open: !!(document.body.innerText.includes('Способ оплаты')),
        new_card_open: !!newCard,
        selected: [...document.querySelectorAll('.pm-row--selected')].map(el => el.textContent.trim())
      });
    }
  }
  return JSON.stringify({
    timed_out: true,
    sheet_open: document.body.innerText.includes('Способ оплаты'),
    inline: document.querySelector('[data-testid="payment-method-inline-error"]')?.textContent?.trim() || null,
    body_snip: document.body.innerText.slice(0, 500)
  });
})()

