  const rb = await rr.json().catch(()=>({}));
  if (rb.refresh_token) localStorage.setItem('shop_refresh_token', rb.refresh_token);
  // get menu product brazil 10
  const cats = await fetch(`/shop/api/categories?tenant_id=${tid}`, {credentials:'same-origin', headers:{Accept:'application/json'}}).then(r=>r.json());
  // add via cart API - find product id from page
  const pid = location.hash.match(/product\/([a-f0-9-]+)/)?.[1];
