  return JSON.stringify({ refresh: rr.status, add: add.status, addBody: {total: addBody.total || addBody.cart?.total, err: addBody.error}, cards: (cards.cards||[]).map(c=>({id:c.id, mask:c.card_masked||c.label||c.mask})) });
