(async () => {
  // close status overlays
  const hide = [...document.querySelectorAll('button')].find(b => /Скрыть статус|Закрыть|×|✕/.test(b.textContent||'') || b.getAttribute('aria-label')?.includes('закрыть'));
  if (hide) hide.click();
  const xBtns = [...document.querySelectorAll('button, [role=button]')].filter(b => (b.textContent||'').trim() === '×' || (b.textContent||'').trim() === '✕');
  xBtns.forEach(b => b.click());
  await new Promise(r => setTimeout(r, 400));
  const payCta = [...document.querySelectorAll('button')].find(b => /\+358₽|\+\d+₽/.test(b.textContent||'') && !b.disabled);
  if (payCta) payCta.click();
  await new Promise(r => setTimeout(r, 800));
  // go checkout if needed
  if (!document.body.innerText.includes('Способ оплаты')) {
    location.hash = '#/checkout';
    await new Promise(r => setTimeout(r, 1000));
    const pay2 = [...document.querySelectorAll('button')].find(b => /\+\d+₽/.test(b.textContent||'') && !b.disabled);
    if (pay2) pay2.click();
    await new Promise(r => setTimeout(r, 800));
  }
  return JSON.stringify({
    hasSheet: document.body.innerText.includes('Способ оплаты'),
    cardBtns: [...document.querySelectorAll('button')].map(b=>b.textContent.trim()).filter(t=>/Картой|Оплатить|СБП/.test(t))
  });
})()

